#include <stdio.h>

#define N 3

int main() {
    int m[N][N] = {{1, 2, 3}, {4, 5, 6}, {7, 8, 10}};
    int main_diag = 0, anti_diag = 0;
    for (int i = 0; i < N; i++) {
        main_diag += m[i][i];
        anti_diag += m[i][N - 1 - i];
    }
    printf("%d %d\n", main_diag, anti_diag);
    return 0;
}
